package datapool

import (
	"chatapp/backend/config"
	"chatapp/backend/log"
	"chatapp/backend/model"
	"fmt"
	"time"

	"go.uber.org/zap"
	"gorm.io/driver/mysql"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

var _db *gorm.DB

func Init() {
	if _db != nil {
		return
	}

	username := config.GetSqlConfig().User     //账号
	password := config.GetSqlConfig().Password //密码
	host := config.GetSqlConfig().Host         //数据库地址，可以是Ip或者域名
	port := config.GetSqlConfig().Port         //数据库端口
	Dbname := config.GetSqlConfig().Name       //数据库名
	timeout := "10s"                           //连接超时，10秒

	//拼接下dsn参数, dsn格式可以参考上面的语法，这里使用Sprintf动态拼接dsn参数，因为一般数据库连接参数，我们都是保存在配置文件里面，需要从配置文件加载参数，然后拼接dsn。
	dsn := fmt.Sprintf(
		"%s:%s@tcp(%s:%d)/%s?charset=utf8mb4&parseTime=True&loc=Local&timeout=%s",
		username,
		password,
		host,
		port,
		Dbname,
		timeout,
	)
	var err error

	//连接MYSQL, 获得DB类型实例，用于后面的数据库读写操作。
	_db, err = gorm.Open(mysql.Open(dsn), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Info),
	})
	if err != nil {
		panic("连接数据库失败, error=" + err.Error())
	}

	err = _db.AutoMigrate(
		&model.User{},
		&model.Message{},
		&model.Group{},
		&model.GroupMember{},
		&model.UserFriend{},
	)
	if err != nil {
		log.Logger.Error("自动迁移失败", zap.Error(err))
	}

	sqlDB, err := _db.DB()
	if err != nil {
		panic("获取 sql.DB 失败, error=" + err.Error())
	}

	//设置数据库连接池参数
	sqlDB.SetMaxOpenConns(100) //设置数据库连接池最大连接数
	sqlDB.SetMaxIdleConns(20)  //连接池最大允许的空闲连接数，如果没有sql任务需要执行的连接数大于20，超过的连接会被连接池关闭。
	sqlDB.SetConnMaxIdleTime(10 * time.Minute)
	sqlDB.SetConnMaxLifetime(2 * time.Hour)
}

func GetDB() *gorm.DB {
	if _db == nil {
		panic("database not initialized, call datapool.Init() first")
	}
	return _db
}

// SetDB allows tests to provide a custom *gorm.DB instance, such as an in-memory sqlite database.
// It replaces the package-level _db variable so that service/router code using datapool.GetDB()
// will operate on the supplied database.
func SetDB(db *gorm.DB) {
	_db = db
}

// 数据库终端命令行
//sudo mysql -u root -p

package model

import(
	"gorm.io/gorm"
	"time"
)

type User struct {
	gorm.Model
	Uuid     string     `json:"uuid" gorm:"type:varchar(150);not null;unique_index:idx_user_uuid;comment:'uuid'"`
	Username string     `json:"username" form:"username" binding:"required" gorm:"unique;not null; comment:'用户名'"`
	Password string     `json:"password" form:"password" binding:"required" gorm:"type:varchar(150);not null; comment:'密码'"`
	Nickname string     `json:"nickname" gorm:"comment:'昵称'"`
	Avatar   string     `json:"avatar" gorm:"type:varchar(255);comment:'头像'"`
	Email    string     `json:"email" gorm:"type:varchar(80);column:email;comment:'邮箱'"`
}

type Group struct {
	gorm.Model
	Uuid    string `json:"uuid" gorm:"type:varchar(36);not null;uniqueIndex:idx_group_uuid;comment:'uuid'"`
	OwnerId uint   `json:"userId" gorm:"index;comment:'群主ID'"`
	Name    string `json:"name" gorm:"type:varchar(48);not null;comment:'群名称'"`
	Notice  string `json:"notice" gorm:"type:varchar(350);comment:'群公告'"`
	Avatar  string `json:"avatar" gorm:"type:varchar(255);comment:'群头像'"`
}

// GroupMember 群成员关系表
type GroupMember struct {
	gorm.Model
	GroupId uint `gorm:"index;uniqueIndex:idx_group_member"`
	UserId  uint `gorm:"index;uniqueIndex:idx_group_member"`
	// 显式定义关联，方便 GORM Preload
	MemberDetail User  `gorm:"foreignKey:UserId;references:ID"`
	GroupDetail  Group `gorm:"foreignKey:GroupId;references:ID"`
}


type Message struct {
	gorm.Model
	Uuid      string `gorm:"uniqueIndex;not null"`
	FromUser  string `gorm:"index;not null"` // 发送者 UUID
	ToTarget  string `gorm:"index;not null"` // 接收者 UUID (用户UUID或群组UUID)
	Content   string `gorm:"type:text"`      // 消息内容
	MsgType   int    `gorm:"default:1"`      // 1:私聊, 2:群聊
	IsRead    bool   `gorm:"default:false"`
	// 显式定义发送者关联
	Sender    User   `gorm:"foreignKey:FromUser;references:Uuid"`
}

type UserFriend struct {
	gorm.Model
	UserId   uint `json:"userId" gorm:"index;uniqueIndex:idx_user_friend;comment:'用户ID'"`
	FriendId uint `json:"friendId" gorm:"index;uniqueIndex:idx_user_friend;comment:'好友ID'"`

	// 显式定义关联，方便 GORM Preload
	FriendDetail User `gorm:"foreignKey:FriendId;references:ID"`
}

type ResponseMsg struct {
	Code int         `json:"code"`
	Msg  string      `json:"msg"`
	Data interface{} `json:"data"`
}

func SuccessMsg(data interface{}) *ResponseMsg {
	msg := &ResponseMsg{
		Code: 0,
		Msg:  "SUCCESS",
		Data: data,
	}
	return msg
}

func FailMsg(msg string) *ResponseMsg {
	msgObj := &ResponseMsg{
		Code: -1,
		Msg:  msg,
	}
	return msgObj
}

func FailCodeMsg(code int, msg string) *ResponseMsg {
	msgObj := &ResponseMsg{
		Code: code,
		Msg:  msg,
	}
	return msgObj
}

func (u *User) BeforeUpdate(tx *gorm.DB) error {
	tx.Statement.SetColumn("UpdatedAt", time.Now())
	return nil
}

