func Cors() gin.HandlerFunc {
	return func(c *gin.Context) {
		method := c.Request.Method
		origin := c.Request.Header.Get("Origin") //请求头部
		if origin != "" {
			c.Header("Access-Control-Allow-Origin", "*") // 可将将 * 替换为指定的域名
			c.Header("Access-Control-Allow-Methods", "POST, GET, OPTIONS, PUT, DELETE, UPDATE")
			c.Header("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept, Authorization")
			c.Header("Access-Control-Expose-Headers", "Content-Length, Access-Control-Allow-Origin, Access-Control-Allow-Headers, Cache-Control, Content-Language, Content-Type")
			c.Header("Access-Control-Allow-Credentials", "true")
		}
		//允许类型校验
		if method == "OPTIONS" {
			c.JSON(http.StatusOK, "ok!")
		}

		defer func() {
			if err := recover(); err != nil {
				log.Logger.Error("HttpError", zap.Any("HttpError", err))
			}
		}()

		c.Next()
	}
}

func Recovery(c *gin.Context) {
	defer func() {
		if r := recover(); r != nil {
			log.Logger.Error("gin catch error: ", log.Any("gin catch error: ", r))
			c.JSON(http.StatusOK, model.FailMsg("系统内部错误"))
		}
	}()
	c.Next()
}

这两个中间键是干什么的

## 这两个中间件的作用

### 1. Cors() - 跨域资源共享

处理**浏览器跨域请求**问题。

```go
func Cors() gin.HandlerFunc {
    return func(c *gin.Context) {
        // 设置响应头，允许跨域访问
        c.Header("Access-Control-Allow-Origin", "*")        // 允许所有域名
        c.Header("Access-Control-Allow-Methods", "...")    // 允许的请求方法
        c.Header("Access-Control-Allow-Headers", "...")    // 允许的请求头
        c.Header("Access-Control-Allow-Credentials", "true") // 允许携带凭证

        // OPTIONS 预检请求，直接返回
        if method == "OPTIONS" {
            c.JSON(http.StatusOK, "ok!")
        }

        c.Next()  // 继续执行后续处理
    }
}
```

**浏览器跨域限制**：网页只能向同域名发送 AJAX 请求。如果你的前端 `localhost:3000` 调用后端 `localhost:8081`，浏览器会阻止，需要这个中间件放行。

---

### 2. Recovery() - 异常捕获

捕获 panic，防止服务器崩溃。

```go
func Recovery(c *gin.Context) {
    defer func() {
        if r := recover(); r != nil {
            // 捕获到 panic，记录日志
            log.Logger.Error("gin catch error: ", log.Any("gin catch error: ", r))
            // 返回友好错误信息给客户端
            c.JSON(http.StatusOK, model.FailMsg("系统内部错误"))
        }
    }()
    c.Next()
}
```

**作用**：
- 代码 panic 时不会直接崩溃
- 返回 JSON 错误而不是 500 空页面
- 记录错误日志便于排查

---

## 对比

| 中间件 | 作用 | 场景 |
|--------|------|------|
| **Cors** | 解决跨域限制 | 前端域名 ≠ 后端域名 |
| **Recovery** | 防止 panic 导致服务崩溃 | 任何异常情况 |

---

## 小问题

你的 `Cors()` 里有嵌套的 `defer recover()`，这其实是**多余的**，因为后面有独立的 `Recovery()` 中间件。可以简化：

```go
func Cors() gin.HandlerFunc {
    return func(c *gin.Context) {
        // 跨域头设置
        // ...

        if method == "OPTIONS" {
            c.JSON(http.StatusOK, "ok!")
            return  // OPTIONS 直接返回，无需 Next
        }
        c.Next()
    }
}
```

